  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the booking price after applying eligible membership discount.
   * Algorithm:
   * 1. If customer or bookingTime is null, return the original trip price.
   * 2. If customer has no membershipPackage, return the original trip price.
   * 3. If membershipPackage does not contain DISCOUNTS, return the original trip price.
   * 4. Check whether bookingTime is at least 24 hours before this trip's departure time.
   * 5. If the 24-hour condition is not satisfied, return the original trip price.
   * 6. Otherwise compute price * 0.8.
   * 7. Round the result to one decimal place.
   * 8. Return the discounted price.
   * Related Features:
   * - price
   * - departureTime
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   * - customer : Customer
   *   - Booking customer; may be null.
   * - bookingTime : String
   *   - Time at which booking is made; must be comparable with trip departureTime.
   * Output:
   * - double
   * - Final booking price after discount evaluation.
   * - Returned value preserves one decimal place.
   * Pre-condition:
   * - price is defined.
   * - departureTime is valid and comparable.
   * - bookingTime, if non-null, uses the same time representation as departureTime.
   * Post-condition:
   * - No object state is changed.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
      return price;
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
      return price;
    if (departureTime == null)
      return price;
    try
    {
      java.time.LocalDateTime bookingDateTime = java.time.LocalDateTime.parse(bookingTime);
      java.time.LocalDateTime departureDateTime = java.time.LocalDateTime.parse(departureTime);
      if (!bookingDateTime.isBefore(departureDateTime.minusHours(24)))
        return price;
    }
    catch (Exception e)
    {
      return price;
    }
    return Math.round((price * 0.8) * 10.0) / 10.0;
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Compute reward points earned for this trip's bookings during a given month for a customer.
   * Algorithm:
   * 1. Return 0 if customer or currentMonth is null.
   * 2. Return 0 if customer has no membershipPackage.
   * 3. Return 0 if membershipPackage does not contain POINTS.
   * 4. Iterate over this trip's bookings.
   * 5. For each booking owned by the given customer, if booking.isInMonth(currentMonth) is true, add 5 points per booked seat.
   * 6. Return the total points.
   * Related Features:
   * - bookings
   * - price
   * Related Classes: Booking, Customer, MembershipPackage, Award
   * Input:
   * - customer : Customer
   *   - Customer whose points are being computed.
   * - currentMonth : String
   *   - Requested month in the system-supported month format.
   * Output:
   * - int
   * - Total reward points for the specified customer in the specified month.
   * - Each seat contributes 5 points.
   * Pre-condition:
   * - customer and currentMonth are non-null.
   * - Bookings have valid booking dates.
   * Post-condition:
   * - No object state is changed.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
      return 0;
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
      return 0;
    int total = 0;
    for (Booking booking : getBookings())
    {
      if (booking != null && booking.getCustomer() == customer && booking.isInMonth(currentMonth))
        total += booking.getNumberOfSeats() * 5;
    }
    return total;
    
  }

